-- Phase 3: Karnataka geography. Tables here; the data is in the next migration
-- (generated by scripts/geo/build_karnataka.py), so hosted databases get it too.
-- Public reference data: anyone may read it, nobody may change it through the API.

create table public.karnataka_boundary (
  id smallint primary key default 1 check (id = 1),     -- exactly one row
  geom extensions.geography(MultiPolygon, 4326) not null,
  source text not null,
  loaded_at timestamptz not null default now()
);

create table public.districts (
  id smallint primary key,
  name_en text not null unique,
  name_kn text not null,
  former_names text[] not null default '{}',             -- e.g. Bangalore, Gulbarga: helps search
  lgd_code int unique,                                   -- Local Government Directory code (to fill in)
  geom extensions.geography(MultiPolygon, 4326) not null
);

create table public.taluks (
  id int primary key,
  district_id smallint not null references public.districts (id),
  name_en text not null,
  name_kn text,                                          -- to fill in from LGD; app falls back to English
  former_names text[] not null default '{}',
  census2011_code text,
  lgd_code int unique,
  is_urban boolean,                                      -- decides 5 km vs 20 km search radius (phase 4)
  geom extensions.geography(MultiPolygon, 4326) not null,
  unique (district_id, name_en)
);

create index karnataka_boundary_geom_idx on public.karnataka_boundary using gist (geom);
create index districts_geom_idx on public.districts using gist (geom);
create index taluks_geom_idx on public.taluks using gist (geom);
create index taluks_district_id_idx on public.taluks (district_id);

alter table public.karnataka_boundary enable row level security;
alter table public.districts enable row level security;
alter table public.taluks enable row level security;

create policy "karnataka_boundary: anyone can read" on public.karnataka_boundary for select to anon, authenticated using (true);
create policy "districts: anyone can read" on public.districts for select to anon, authenticated using (true);
create policy "taluks: anyone can read" on public.taluks for select to anon, authenticated using (true);

revoke all on public.karnataka_boundary, public.districts, public.taluks from anon, authenticated;
grant select on public.karnataka_boundary, public.districts, public.taluks to anon, authenticated;

-- Is this point inside Karnataka? Invalid coordinates are simply "no".
create function public.is_in_karnataka(lat double precision, lng double precision)
returns boolean
language sql
stable
set search_path = ''
as $$
  select lat between -90 and 90
     and lng between -180 and 180
     and exists (
       select 1 from public.karnataka_boundary b
       where extensions.st_covers(b.geom, extensions.st_setsrid(extensions.st_point(lng, lat), 4326)::extensions.geography)
     );
$$;

-- Which district and taluk is this point in? No rows if it is outside Karnataka.
-- Points in tiny gaps between simplified taluk shapes go to the nearest taluk.
create function public.locate_in_karnataka(lat double precision, lng double precision)
returns table (
  district_id smallint, district_name_en text, district_name_kn text,
  taluk_id int, taluk_name_en text, taluk_name_kn text
)
language sql
stable
set search_path = ''
as $$
  with p as (select extensions.st_setsrid(extensions.st_point(lng, lat), 4326)::extensions.geography g)
  select d.id, d.name_en, d.name_kn, t.id, t.name_en, t.name_kn
  from p
  cross join lateral (
    select t.* from public.taluks t
    order by (not extensions.st_covers(t.geom, p.g)), t.geom operator(extensions.<->) p.g
    limit 1
  ) t
  join public.districts d on d.id = t.district_id
  where public.is_in_karnataka(lat, lng);
$$;

revoke execute on function public.is_in_karnataka(double precision, double precision) from public;
revoke execute on function public.locate_in_karnataka(double precision, double precision) from public;
grant execute on function public.is_in_karnataka(double precision, double precision) to anon, authenticated, service_role;
grant execute on function public.locate_in_karnataka(double precision, double precision) to anon, authenticated, service_role;
